INSERT INTO `knowledge_chunks` VALUES (526,'multi-agent-security/08-maintenance-and-version.md',0,'# 多 Agent 协作安全 — 维保升级与版本发布 ## 升级流程 - 升级前：备份可信策略、防污染规则库与密钥配置，核对版本兼容矩阵 - 升级中：在低峰期执行，先升级可信层，再升级防污染与编排面防护组件 - 升级后：执行消息签名/验签与防污染回归，核对策略与密钥状态 - 建议升级频率：季度安全补丁、月度规则库更新、年度大版本演进 ## 补丁管理 - 安全补丁（签名算法缺陷、注入绕过分流）随版本发布，高危缺陷 24 小时内出补丁 - 防污染规则库每周更新，重大威胁即时推送，支持一键更新 ## 版本历史 - v1.0：首个商用版本，支持消息签名与完整性校验 - v1.2：新增防污染引擎与注入模式库，支持主流编排框架 - v1.5：引入编排面访问控制与任务路由校验 - v2.0：消息校验吞吐提升至 50 万条/秒，支持 A2A/MCP 协议 ## 兼容性 - SDK 向后兼容一个主版本；消息协议优先向上兼容 - 升级前确认与编排框架、IAM、审计产品及密钥体系版本匹配 ## 退役/下线策略 - 退役前提供策略与密钥导出、消息回放验证工具，确保协作链路可切换 - 下线流程包括：确认替代方案、导出防护策略、执行下线','[0.020140396431088448,0.018982043489813805,0.004742396995425224,-0.05978596210479736,-0.03201039880514145,0.023391257971525192,-0.005748170893639326,-0.023341435939073563,-0.0013981196098029613,-0.0025969527196139097,-0.02735207788646221,-0.005586250685155392,-0.003168344497680664,0.002916122553870082,-0.02258165553212166,0.024512244388461113,8.640939631732181e-05,-0.04115267097949982,0.01348920725286007,0.043892860412597656,-0.026355644688010216,-0.0033100247383117676,0.0347754992544651,0.018695568665862083,0.024549610912799835,0.07802067697048187,0.035796843469142914,0.04523804411292076,-0.00274174683727324,-0.0263307336717844,0.02193397469818592,0.07562924176454544,-0.00864405371248722,-0.005028871353715658,0.03333067521452904,0.06023435667157173,0.0397825762629509,0.006255729123950005,0.008706330321729183,-0.017898421734571457,-0.04491420462727547,0.042124193161726,0.02017776295542717,0.00288187013939023,-0.018334360793232918,0.046334121376276016,-0.004300229717046022,-0.00021680195641238242,-0.0013747657649219036,-0.0032757725566625595,0.039010338485240936,-0.025471311062574387,-0.010848660953342915,0.009011488407850266,0.02555849775671959,0.047754038125276566,-0.012735655531287193,-0.01842154935002327,-0.012941169552505016,-0.04232347756624222,0.034227464348077774,-0.014934035018086433,0.016391318291425705,-0.001754655735567212,0.01989128813147545,0.01757458